#include "rs485_vector_decoder.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>

/* Published Modbus request: device 1, read 10 holding registers at address 0.
 * Literal CRC bytes are not generated by the implementation under test. */
static const uint8_t request[] = {1,3,0,0,0,10,0xc5,0xcd};
static tracegpu_rs485_vector_decoder decoder;
static tracegpu_modbus_frame results[32];
static tracegpu_uart_decode_config config;
static unsigned count, sequence, levels, inverted, tests;
static uint64_t tick;

static void emit(const tracegpu_modbus_frame *f, void *ctx) {
    (void)ctx;
    assert(count < 32);
    results[count++] = *f;
}
static void event(unsigned type, uint64_t when, unsigned wire_levels) {
    tracegpu_vector_event e = {when,sequence++,(uint8_t)type,
        type == TG_VEC_GAP ? 1 : 255,(uint8_t)wire_levels};
    tracegpu_vector_record record = tracegpu_vector_pack(e);
    e = tracegpu_vector_unpack(&record);
    assert(!tracegpu_rs485_vector_event(&decoder, &e));
}
static void wire(unsigned logical, uint64_t when) {
    unsigned next = (levels & ~(1U << config.channel)) |
        ((logical ^ inverted) << config.channel);
    if (next != levels) {
        levels = next;
        event(TG_VEC_CHANGE, when, levels);
    }
}
static uint64_t bit_at(uint64_t start, unsigned bit) {
    return start + ((uint64_t)bit * 100000000U + config.baud/2) / config.baud;
}
static void byte(unsigned value, unsigned errors) {
    unsigned b = 0, ones = 0;
    uint64_t start = tick;
    wire(0, bit_at(start,b++));
    for (unsigned i=0; i<8; i++) {
        unsigned v = (value>>i)&1;
        ones += v;
        wire(v, bit_at(start,b++));
    }
    if (config.parity)
        wire((ones&1U) ^ (config.parity==2) ^ !!(errors&TG_UART_PARITY_ERROR), bit_at(start,b++));
    for (unsigned i=0; i<config.stops; i++)
        wire(errors&TG_UART_FRAME_ERROR ? 0 : 1, bit_at(start,b++));
    tick = bit_at(start,b);
    wire(1,tick);
}
static void begin(unsigned baud, unsigned parity, unsigned stops,
                  unsigned channel, unsigned invert, uint64_t origin) {
    config = (tracegpu_uart_decode_config){baud,(uint8_t)channel,8,(uint8_t)parity,(uint8_t)stops};
    assert(!tracegpu_rs485_vector_begin(&decoder,&config,invert,emit,0));
    count=sequence=0;inverted=invert;
    levels = 255U ^ (invert << channel);
    event(TG_VEC_INIT,origin,levels);
    tick = origin + decoder.modbus.t35_min + 100;
}
static void adu(unsigned errors) {
    for (unsigned i=0; i<sizeof request; i++) byte(request[i],i==3?errors:0);
}
static void end_after_silence(void) {
    tick += decoder.modbus.t35_min;
    event(TG_VEC_END,tick,levels);
}
static unsigned valid_count(void) {
    unsigned valid=0;
    for (unsigned i=0;i<count;i++) valid += results[i].valid!=0;
    return valid;
}
static void formats(void) {
    const unsigned rates[]={4800,9600,19200,38400,57600,115200,230400,460800,921600};
    const unsigned parity[]={0,1,2,0},stops[]={1,1,1,2};
    for(unsigned r=0;r<9;r++) for(unsigned f=0;f<4;f++)
    for(unsigned ch=0;ch<8;ch+=7) for(unsigned inv=0;inv<2;inv++) {
        begin(rates[r],parity[f],stops[f],ch,inv,0x100000000ULL+17);
        adu(0);end_after_silence();
        assert(count==1 && results[0].valid && results[0].complete);
        assert(results[0].length==sizeof request && !memcmp(results[0].adu,request,sizeof request));
        assert(results[0].channel==ch && results[0].direction==TG_MB_DIRECTION_UNKNOWN);
        assert(results[0].start>UINT32_MAX && decoder.characters==8);
        assert(!decoder.input_errors);
        tests++;
    }
}
static void recovery(void) {
    /* GAP must cut the UART before its old-level advance could complete a byte. */
    begin(9600,0,1,0,0,0);
    for(unsigned i=0;i<4;i++) byte(request[i],0);
    wire(0,tick);tick+=100;
    event(TG_VEC_GAP,tick,0);
    tick+=1000000;
    levels=255;event(TG_VEC_RESYNC,tick,levels);
    tick+=decoder.modbus.t35_min;adu(0);end_after_silence();
    assert(valid_count()==1 && count>=2);
    assert(results[0].flags&TG_MB_GAP);
    assert(results[count-1].valid && decoder.characters==12);
    tests++;

    /* A skipped sequence is also a loss, even if the next record looks idle. */
    begin(115200,0,1,0,0,0);byte(1,0);sequence++;
    tick+=200000;event(TG_VEC_WATERMARK,tick,levels);
    tick+=decoder.modbus.t35_min;adu(0);end_after_silence();
    assert(!valid_count() && decoder.input_errors);
    tests++;

    begin(9600,1,1,0,0,0);adu(TG_UART_PARITY_ERROR);end_after_silence();
    assert(count==1 && !results[0].valid && (results[0].flags&TG_MB_PARITY));tests++;
    begin(9600,0,1,0,0,0);adu(0);event(TG_VEC_END,tick,levels);
    assert(count==1 && !results[0].valid && (results[0].flags&TG_MB_TRUNCATED));tests++;

    /* A large initial LOW interval is not an initial proof of bus silence. */
    begin(9600,0,1,0,0,0);
    levels=254;event(TG_VEC_RESYNC,tick,levels);
    tick+=1000000;levels=255;event(TG_VEC_CHANGE,tick,levels);
    tick+=1;adu(0);end_after_silence();
    assert(count==1 && !results[0].valid && (results[0].flags&TG_MB_START_UNKNOWN));tests++;

    begin(9600,0,1,0,0,0);adu(0);
    tick+=decoder.modbus.t35_min;event(TG_VEC_WATERMARK,tick,levels);
    assert(count==1&&results[0].valid);
    tick+=1;adu(0);end_after_silence();assert(count==2&&valid_count()==2);tests++;
}
static void malformed(void) {
    tracegpu_vector_event e;
    begin(9600,0,1,0,0,0);byte(1,0);
    e=(tracegpu_vector_event){decoder.last-1,sequence++,TG_VEC_WATERMARK,255,255};
    assert(tracegpu_rs485_vector_event(&decoder,&e)<0 && decoder.input_errors);
    assert(!valid_count());tests++;
    begin(9600,0,1,0,0,0);
    e=(tracegpu_vector_event){tick,sequence++,TG_VEC_CHANGE,2,0};
    assert(tracegpu_rs485_vector_event(&decoder,&e)<0 && decoder.input_errors);tests++;
    begin(9600,0,1,0,0,0);adu(0);end_after_silence();
    e=(tracegpu_vector_event){tick+1,sequence++,TG_VEC_WATERMARK,255,255};
    assert(tracegpu_rs485_vector_event(&decoder,&e)<0);tests++;
    begin(9600,0,1,0,0,0);adu(0);
    e=(tracegpu_vector_event){tick+decoder.modbus.t35_min,sequence++,TG_VEC_END,255,254};
    assert(tracegpu_rs485_vector_event(&decoder,&e)<0 && !valid_count());tests++;
    begin(9600,0,1,0,0,0);adu(0);
    e=(tracegpu_vector_event){tick+decoder.modbus.t35_min,sequence++,TG_VEC_WATERMARK,255,254};
    assert(tracegpu_rs485_vector_event(&decoder,&e)<0 && !valid_count());tests++;
    begin(9600,0,1,0,0,0);
    e=(tracegpu_vector_event){tick,sequence++,TG_VEC_WATERMARK,1,1};
    assert(tracegpu_rs485_vector_event(&decoder,&e)<0 && decoder.input_errors);tests++;
    begin(9600,0,1,0,0,UINT64_MAX-1000000);
    e=(tracegpu_vector_event){UINT64_MAX-10,sequence++,TG_VEC_CHANGE,255,254};
    assert(tracegpu_rs485_vector_event(&decoder,&e)<0 && decoder.input_errors);
    assert(!decoder.uart.busy && !valid_count());tests++;
    /* Activity on another captured lane is not a selected-UART transition. */
    begin(9600,0,1,0,0,0);adu(0);
    levels ^= 128;event(TG_VEC_CHANGE,tick,levels);end_after_silence();
    assert(count==1&&results[0].valid&&!decoder.input_errors);tests++;
}
static void short_start_activity(void) {
    uint64_t tail,fall,rise;
    begin(9600,0,1,0,0,0);adu(0);tail=tick;
    fall=tail+decoder.modbus.t35_min/2;
    rise=fall+100000000U/config.baud/4;
    wire(0,fall);wire(1,rise);
    tick=tail+decoder.modbus.t35_min;
    event(TG_VEC_WATERMARK,tick,levels);
    /* The receiver rejects the short UART start, but its physical activity
     * still interrupted the RTU t3.5 silence. Never publish the old ADU valid. */
    assert(!valid_count());tests++;
    tick+=decoder.modbus.t35_min;adu(0);end_after_silence();
    assert(valid_count()==1&&results[count-1].valid);tests++;

    /* If silence was already complete BEFORE the glitch, retain that ADU. */
    begin(9600,0,1,0,0,0);adu(0);tail=tick;
    fall=tail+decoder.modbus.t35_min+10;
    rise=fall+100000000U/config.baud/4;
    wire(0,fall);wire(1,rise);
    tick=rise+decoder.modbus.t35_min;event(TG_VEC_END,tick,levels);
    assert(valid_count()==1);tests++;
}
int main(void) {
    formats();recovery();malformed();short_start_activity();
    printf("RS485_VECTOR_V37_PASS scenarios=%u literal_crc=C5CD exact_full_stop=1 packed_abi=1 decoder_bytes=%u\n",
        tests,(unsigned)sizeof decoder);
    return 0;
}
